/* Called from a timer ISR every T = 0.01 s */
float pid_step(float sp, float y) {
    static float integ = 0.0f, e_prev = 0.0f;
    float e = sp - y;
    integ += KI * T * e;
    float u = KP * e + integ + KD * (e - e_prev) / T;
    e_prev = e;
    if (u > U_MAX) { u = U_MAX; integ -= KI * T * e; }  /* anti-windup */
    if (u < U_MIN) { u = U_MIN; integ -= KI * T * e; }
    return u;
}

